import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  const root = new Group();

  // Plane geometry – size chosen to comfortably contain the headline text
  const planeGeom = new PlaneGeometry(2, 0.5);
  const planeMat = new MeshBasicNodeMaterial({
    color: new Color('#0b0b10'), // surface color
    // map will be set asynchronously
  });

  // Load brushed‑metal texture
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      planeMat.map = tex;
      planeMat.needsUpdate = true;
    });
  }

  const planeMesh = new Mesh(planeGeom, planeMat);
  // Slightly offset the plane to avoid Z‑fighting with the text
  planeMesh.position.set(0, 0, 0);
  root.add(planeMesh);

  // Text – headline role
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of textItems) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: '#16161d', // ink color
      align: 'left',
    });
    // Position text slightly in front of the plane
    txt.position.set(0, 0, 0.01);
    root.add(txt);
  }

  // No interactive handlers for this node
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    planeGeom.dispose();
    planeMat.dispose();
    // Dispose any GSAP timelines that might have been created in the future
    gsap.globalTimeline.clear();
  };

  return root;
}
